import Foundation
import CRMCore

func runInboxExistingDealChecks(directory:URL) async throws -> Int {
    var count=0
    func expect(_ value:Bool,_ message:String) throws {guard value else {throw CheckFailure(message:message)};count += 1}
    let d=try JSONSerialization.jsonObject(with:Data(contentsOf:directory.appendingPathComponent("inbox-existing-deal.json"))) as! [String:Any],fixture=FixtureInboxExistingDealPort(directory:directory)
    func context(_ x:[String:Int])->InboxConversationFilesContext {InboxConversationFilesContext(business:x["business"]!,conversation:x["conversation"]!,epoch:x["epoch"]!,revision:x["revision"]!)}
    let c=context(d["context"] as! [String:Int]),source=InboxExistingDealSource.decode(Data((d["source_json"] as! String).utf8),context:c)!,auth=fixture.grants[0].authorization(for:c)!,review=InboxExistingDealReview(source:source,authorization:auth,visit:1)
    for x in d["source_cases"] as! [[String:Any]] {let s=InboxExistingDealSource.decode(Data((x["response_json"] as! String).utf8),context:c);try expect((s != nil)==x["valid"] as! Bool,"Generic existing-Lead source \(x["name"]!)");try expect((s.map {InboxExistingDealReview(source:$0,authorization:auth,visit:1).valid} ?? false)==x["eligible"] as! Bool,"Lead eligibility inferred conversation Client/pipeline")}
    for x in d["grant_cases"] as! [[String:Any]] {let g=try JSONDecoder().decode(SyntheticInboxExistingDealGrant.self,from:JSONSerialization.data(withJSONObject:x["grant"]!));try expect((g.authorization(for:c) != nil)==x["valid"] as! Bool,"Two separate Lead grants \(x["name"]!)")}
    var ledger=InboxExistingDealLedger();let a=ledger.begin(review)!,body=try JSONSerialization.jsonObject(with:a.preparedBody()) as! [String:Any];try expect(body.isEmpty && a.path=="/api/inbox/conversations/901/create-deal/" && a.query.isEmpty && a.headers.isEmpty,"Existing Lead invented message/title/pipeline/body/key/query")
    for x in d["receipt_cases"] as! [[String:Any]] {let receipt=InboxExistingDealReceipt.decode(Data((x["response_json"] as! String).utf8),attempt:a);try expect((receipt != nil)==x["valid"] as! Bool,"Exact direct LeadSerializer \(x["name"]!)");if let receipt {try expect(Mirror(reflecting:receipt).children.count==6,"Lead retained title/status/responsible/grant metadata")}}
    try expect(ledger.begin(review)==nil && !ledger.acknowledge(auth,record:ledger.visible(auth)!),"Pending duplicate/ack");ledger.complete(a,outcome:try await fixture.execute(a));let known=ledger.visible(auth)!;try expect(known.phase == .response && known.result?.id==111 && known.result?.lead==381 && known.result?.client==1701 && known.attempt.review.source.client==701 && known.attempt.review.source.lead==81 && known.attempt.review.source==source,"Existing Lead Client forced equal/fill or source changed");ledger.complete(a,outcome:.unknown);try expect(ledger.visible(auth)==known && ledger.acknowledge(auth,record:known),"Late duplicate overwrote result/history")
    let u=ledger.begin(review)!;ledger.complete(u,outcome:.unknown);let unknown=ledger.visible(auth)!,next=InboxConversationFilesContext(business:101,conversation:901,epoch:1101,revision:2),ns=InboxExistingDealSource.decode(try JSONSerialization.data(withJSONObject:["id":901,"business":101,"deal":111,"lead":NSNull(),"client":NSNull(),"updated_at":"matching Lead new Client input"]),context:next)!,na=fixture.grants[0].authorization(for:next)!
    ledger.complete(u,outcome:try await fixture.execute(u));try expect(ledger.visible(na)==unknown && !ledger.acknowledge(na,record:unknown) && ledger.begin(InboxExistingDealReview(source:ns,authorization:na,visit:2))==nil && unknown.attempt==u && unknown.attempt.review.source.client==701 && known.attempt.review.source.lead==81,"Matching Lead response/reread/new epoch/new conversation Client recovered unknown")
    let other=SyntheticInboxExistingDealGrant(business:101,conversation:901,actor:6001,dealsCreate:true,conversationsUpdate:true).authorization(for:next)!;try expect(ledger.visible(other)==nil && ledger.blocked(business:101,conversation:901) && !ledger.blocked(business:202,conversation:951),"Actor/owner barrier lost")
    for status in [201,202,204,400,403,409,500] {var l=InboxExistingDealLedger();let attempt=l.begin(review)!;if case .response(_,let data)=try await fixture.execute(attempt) {l.complete(attempt,outcome:.response(status:status,data:data))};try expect(l.visible(auth)?.phase == .unknown,"Pipeline201/non-plain200 accepted")}
    var rejection=InboxExistingDealLedger();let rejected=rejection.begin(review)!;rejection.complete(rejected,outcome:.rejectedWithoutWrite);let record=rejection.visible(auth)!;try expect(record.phase == .rejected && rejection.acknowledge(auth,record:record) && rejection.records.count==1,"No-write rejection lost history")
    return count
}
